INSERT INTO `nb_posts` (`post_key`, `user_key`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `post_class`, `post_notice`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_count`, `post_parent`, `post_link`, `post_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(29,	4,	'2023-08-06 06:08:58',	'0000-00-00 00:00:00',	'<p>999999999</p>',	'페북 왜 공지를 안하십니까! 열받게하네',	'',	'publish',	'open',	'open',	0,	'',	'',	'',	'',	'0000-00-00 00:00:00',	'0000-00-00 00:00:00',	'',	0,	0,	'',	0,	'community',	'',	0),
(32,	4,	'2023-08-06 06:15:09',	'0000-00-00 00:00:00',	'<figure class=\"image image_resized\" style=\"width:700px;\"><img src=\"https://imgnews.pstatic.net/image/138/2023/08/05/0002153876_002_20230805140601304.jpg?type=w647\"></figure><p style=\"text-align:center;\"><i>[일론 머스크 ⓒ연합뉴스]</i></p><p><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">[디지털데일리 박세아 기자] X플랫폼(구 트위터)을 둘러싸고 가상자산 론칭, 가상자산 거래 허용 등 다양한 소문이 돌고 있는 가운데 일론 머스크가 자신의 X플랫폼이 자체 가상자산을 출시할 계획이 없음을 분명히 했다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">4일(현지시간) 도지코인 디자이너가 자신의 트위터 계정에 \"테슬라 최고경영자(CEO) 일론 머스크와 X는 가상자산을 출시한적 없다\"라고 언급하자 일론 머스크가 \"앞으로도 그럴 일 없다\"라고 말했다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">현재 X는 메타 스레드 광풍으로 인해 과거 트위터가 이에 반격하고자 리뉴얼한 것이다. 지난 3월 머스크는 X법인을 설립하고 트위터를 합병했다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">머스크는 트위터의 대대적 변화를 예고하며 \"향후 몇 달 안에 우리는 종합적인 커뮤니케이션과 금융 전반을 관리할 수 있는 기능을 추가할 것\"이라고 말한 바 있다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">이 때 머스크가 언급한 \'금융 기능\' 때문에 시장에서는 X의 자체 코인 출시나, 도지코인 거래 기능 접목 등 소문이 무성했다. 특히 도지코인은 머스크가 보유하고 있어 트위터의 변화에 가격이 민감하게 반응해왔다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">도지코인은 2013년 소프트웨어 개발자인 빌리 마커스와 잭슨 팔머가 만든 밈코인이다. 속성상 인기에 의해 가치가 결정되기 때문에 바탕 자산이나 플랫폼이 없어 투기 코인의 성격이 강하다. 하지만, 실제 금융 거래에 도지코인이 쓰인다면 실질적 효용 가치가 생기기 때문에 가격 상승요인이 된다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">머스크는 단순 도지코인 보유자에서 나아가 그동안 \'도지 파더\'를 자청하며 도지코인에 대한 애정을 드러내는 행보를 보였기 때문에 트위터를 인수할 때도 가격이 폭등한 바 있다. 머스크가 트위터 인수 의향을 밝힌 직후 도지코인은 일주일 만에 약 117% 넘게 급등했다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">이후 도지코인의 고로가 시바견이기 때문에 트위터가 시바견으로 로고를 임시 변경했을 당시에도 가격이 일순간 약 35% 올랐었다.</span><br><br><span style=\"background-color:rgb(255,255,255);color:rgb(48,48,56);\">하지만, 아직까지 머스크는 도지코인을 트위터에서 탈바꿈한 X의 결제수단으로 정했다고 공식적으로 언급한 바 없다.</span></p>',	'머스크, \'가상자산 출시\' 소문 일축…\"앞으로도 그럴 일 없어\"',	'',	'publish',	'open',	'open',	0,	'',	'',	'',	'',	'0000-00-00 00:00:00',	'0000-00-00 00:00:00',	'',	0,	0,	'',	0,	'community',	'',	0),
